import { Loader2 } from "lucide-react";
import { useRef } from "react";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/thornberry/components/button";
import {
  DialogBackdrop,
  DialogContent,
  DialogDescription,
  DialogPortal,
  DialogPositioner,
  DialogRoot,
  DialogTitle,
} from "@/registry/thornberry/components/dialog";
import { Label } from "@/registry/thornberry/components/label";
import { PasswordInput } from "@/registry/thornberry/components/password-input";
import { PromptSuggestions } from "@/registry/thornberry/components/prompt-suggestions";

import type { ComponentProps, ReactNode } from "react";
import type { PromptSuggestion } from "@/registry/thornberry/components/prompt-suggestions";

/**
 * Which affordance the panel leads with:
 * - `generate`: signed in or a key is set, so Generate runs
 * - `signIn`: no identity and no key, but sign-in is available
 * - `needsKey`: no identity, no sign-in, so a key is the only path
 */
export type AiDescribeMode = "generate" | "signIn" | "needsKey";

export interface AiDescribePanelProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Which affordance to lead with. The host resolves this from auth + key state. */
  mode: AiDescribeMode;
  /** Dialog heading. */
  title?: string;
  /** Short line under the heading. */
  description?: ReactNode;

  /** The prompt text (controlled). */
  prompt: string;
  onPromptChange: (prompt: string) => void;
  placeholder?: string;
  /**
   * Example prompts shown as chips under the prompt while it is empty (see
   * `PromptSuggestions`): drawn in a random order per open, with "More ideas"
   * when there are more than `suggestionCount`. A pick hands its prompt to
   * `onPickSuggestion` and focuses the prompt; it never generates outright
   */
  suggestions?: readonly (string | PromptSuggestion)[];
  /** How many example prompts show at once. Defaults to 4 */
  suggestionCount?: number;
  onPickSuggestion?: (prompt: string) => void;

  /** Fire a generation with the current prompt. */
  onGenerate: () => void;
  /** While true the dialog cannot be dismissed and inputs are disabled. */
  isPending?: boolean;
  generateLabel?: string;
  /**
   * A short live status shown beside a spinner while `isPending`, so a long
   * multi-step generation reads as progress rather than a frozen button (e.g.
   * "Generating...", "Checking the render...", "Refining..."). The host advances
   * it as its own pipeline moves; when omitted the panel just shows the spinner
   */
  pendingLabel?: ReactNode;
  /**
   * A persistent info slot in the footer, left of the actions: the strategic
   * place for host context the user weighs right before spending, e.g. a credit
   * balance and a per-run cost estimate. Hidden while `isPending` (the live
   * status takes its place). Presentational only; the host owns the content
   */
  meta?: ReactNode;

  /** Start sign-in (shown as the primary CTA in `signIn` mode). */
  onSignIn?: () => void;
  signInLabel?: string;

  /**
   * A notice slot, e.g. an error, an out-of-credits message with an upgrade CTA,
   * or a "credits spent" note after a failed-but-billed attempt. The host builds
   * it from `classifyGatewayError`; the panel just renders it
   */
  notice?: ReactNode;

  /** Bring-your-own-key section (a Synapse key, not a raw provider key). */
  byok?: {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    value: string;
    onValueChange: (value: string) => void;
    /** Where to mint a key; rendered as a link when present. */
    keyUrl?: string;
    label?: string;
    placeholder?: string;
  };
}

/** A styled textarea matching the input primitive's tokens (Thornberry ships no textarea). */
const PromptTextarea = ({
  className,
  ...props
}: ComponentProps<"textarea">) => (
  <textarea
    className={cn(
      "flex min-h-24 w-full resize-y rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-xs outline-none transition-[color,box-shadow] placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-50",
      className,
    )}
    {...props}
  />
);

/**
 * Describe-to-draft panel: the shared "describe it in plain English, review the
 * draft" entry point for the fleet's AI-creation flow (Facet models, Fractal
 * services). Presentational only: the host injects generation, sign-in, and the
 * Synapse key state (typically from `@omnidotdev/providers/ai-client`), so this
 * owns no network, auth, or billing logic. A draft never auto-applies; the host
 * closes the panel and shows the result for review.
 */
const AiDescribePanel = ({
  open,
  onOpenChange,
  mode,
  title = "Describe it",
  description,
  prompt,
  onPromptChange,
  placeholder = "Describe what you want to build",
  suggestions,
  suggestionCount,
  onPickSuggestion,
  onGenerate,
  isPending = false,
  generateLabel = "Generate",
  pendingLabel,
  meta,
  onSignIn,
  signInLabel = "Sign in",
  notice,
  byok,
}: AiDescribePanelProps) => {
  const promptRef = useRef<HTMLTextAreaElement>(null);

  const showSuggestions =
    mode === "generate" &&
    prompt.trim().length === 0 &&
    suggestions &&
    suggestions.length > 0;

  const canGenerate = mode === "generate" && prompt.trim().length > 0;

  return (
    <DialogRoot
      open={open}
      onOpenChange={(details) => {
        if (!isPending) onOpenChange(details.open);
      }}
    >
      <DialogPortal>
        <DialogBackdrop />

        <DialogPositioner>
          <DialogContent>
            <div className="flex flex-col gap-1.5">
              <DialogTitle>{title}</DialogTitle>
              {description && (
                <DialogDescription>{description}</DialogDescription>
              )}
            </div>

            {mode !== "needsKey" && (
              <div className="space-y-2">
                <PromptTextarea
                  ref={promptRef}
                  value={prompt}
                  onChange={(event) => onPromptChange(event.target.value)}
                  onKeyDown={(event) => {
                    // Cmd/Ctrl+Enter submits, so the textarea keeps plain Enter
                    if (
                      (event.metaKey || event.ctrlKey) &&
                      event.key === "Enter" &&
                      canGenerate &&
                      !isPending
                    ) {
                      event.preventDefault();
                      onGenerate();
                    }
                  }}
                  placeholder={placeholder}
                  disabled={isPending || mode === "signIn"}
                  aria-label={title}
                />

                {showSuggestions && (
                  <PromptSuggestions
                    suggestions={suggestions}
                    count={suggestionCount}
                    disabled={isPending}
                    onPick={(picked) => {
                      onPickSuggestion?.(picked);
                      promptRef.current?.focus();
                    }}
                  />
                )}
              </div>
            )}

            {notice && (
              <div className="text-muted-foreground text-sm">{notice}</div>
            )}

            {byok && (
              <div className="space-y-2">
                <button
                  type="button"
                  className="text-muted-foreground cursor-pointer text-sm underline-offset-4 hover:underline"
                  onClick={() => byok.onOpenChange(!byok.open)}
                  aria-expanded={byok.open}
                >
                  {byok.label ?? "Use your own Synapse key"}
                </button>

                {byok.open && (
                  <div className="space-y-1.5">
                    <Label htmlFor="ai-byok-key">
                      {byok.label ?? "Synapse API key"}
                    </Label>
                    <PasswordInput
                      id="ai-byok-key"
                      value={byok.value}
                      onChange={(event) =>
                        byok.onValueChange(event.target.value)
                      }
                      placeholder={byok.placeholder ?? "Synapse API key"}
                      autoComplete="off"
                      spellCheck={false}
                      disabled={isPending}
                    />
                    {byok.keyUrl && (
                      <p className="text-muted-foreground text-xs">
                        Need a key?{" "}
                        <a
                          href={byok.keyUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="underline underline-offset-4"
                        >
                          Create a Synapse key
                        </a>
                      </p>
                    )}
                  </div>
                )}
              </div>
            )}

            {/* On a phone the meta sits above the actions instead of being
                squeezed into a narrow column beside them */}
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              {/* Left: a live status while pending (so a multi-step run reads as
                  progress), otherwise the host's meta (credits, cost estimate).
                  Keeps the row present so the actions never shift */}
              <div className="text-muted-foreground min-w-0 flex-1 text-xs">
                {isPending ? (
                  <span className="inline-flex items-center gap-1.5">
                    <Loader2 className="size-3 shrink-0 animate-spin" />
                    {pendingLabel ? (
                      <span className="truncate">{pendingLabel}</span>
                    ) : null}
                  </span>
                ) : (
                  (meta ?? null)
                )}
              </div>

              <div className="flex shrink-0 justify-end gap-2">
                <Button
                  variant="outline"
                  onClick={() => onOpenChange(false)}
                  disabled={isPending}
                  className="pointer-coarse:min-h-11"
                >
                  Cancel
                </Button>
                {mode === "signIn" ? (
                  <Button
                    onClick={onSignIn}
                    disabled={isPending || !onSignIn}
                    className="pointer-coarse:min-h-11"
                  >
                    {signInLabel}
                  </Button>
                ) : (
                  <Button
                    onClick={onGenerate}
                    disabled={isPending || !canGenerate}
                    className="pointer-coarse:min-h-11"
                  >
                    {isPending ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      generateLabel
                    )}
                  </Button>
                )}
              </div>
            </div>
          </DialogContent>
        </DialogPositioner>
      </DialogPortal>
    </DialogRoot>
  );
};

export { AiDescribePanel };

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};

import { ark } from "@ark-ui/react";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

import type { VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";

const buttonVariants = cva(
  "focus-visible:ring-offset-background focus-visible:ring-primary aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap outline-hidden transition-[color,box-shadow,transform] outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        solid:
          "bg-primary text-primary-foreground hover:bg-primary/90 shadow-xs",
        outline:
          "bg-background hover:bg-accent hover:text-accent-foreground border shadow-xs",
        muted: "bg-muted text-muted-foreground hover:bg-muted/80 shadow-xs",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-2 hover:underline",
        destructive:
          "bg-destructive text-background hover:bg-destructive/90 shadow-xs focus-visible:ring-red-500 aria-invalid:ring-red-500/20 dark:aria-invalid:ring-red-500/40",
        // no-style escape hatch: render the bare element and style it via
        // className (widely used downstream for icon/link-like buttons)
        unstyled: "",
      },
      size: {
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        md: "h-9 px-4 py-2 has-[>svg]:px-3",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "solid",
      size: "md",
    },
  },
);

const Button = ({
  className,
  variant,
  size,
  ...rest
}: ComponentProps<typeof ark.button> & VariantProps<typeof buttonVariants>) => (
  <ark.button
    type="button"
    className={cn(buttonVariants({ variant, size }), className)}
    {...rest}
  />
);

export { Button, buttonVariants };

import { Dialog as ArkDialog } from "@ark-ui/react/dialog";
import { Portal } from "@ark-ui/react/portal";
import { X } from "lucide-react";

import { cn } from "@/lib/utils";

import type { ComponentProps } from "react";

const DialogProvider = ArkDialog.RootProvider;
const DialogContext = ArkDialog.Context;
const DialogRoot = ArkDialog.Root;

/**
 * Portals the dialog's backdrop and positioner to the document body. Without it
 * the `fixed inset-0` backdrop and positioner render inline in the DOM, so any
 * ancestor with a `transform`, `filter`, or `backdrop-filter` (page/route
 * transitions, blurred panels) becomes their containing block and the overlay no
 * longer covers the full viewport. Wrap every dialog's backdrop + positioner in
 * this so they always resolve against the viewport.
 */
const DialogPortal = Portal;

const DialogTrigger = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Trigger>) => (
  <ArkDialog.Trigger className={cn("", className)} {...rest} />
);

const DialogBackdrop = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Backdrop>) => (
  <ArkDialog.Backdrop
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-background/80 backdrop-blur-sm data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const DialogPositioner = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Positioner>) => (
  <ArkDialog.Positioner
    className={cn(
      // `p-4` keeps a gutter so a dialog never runs edge to edge on a phone
      "fixed inset-0 z-50 flex items-center justify-center p-4",
      className,
    )}
    {...rest}
  />
);

/**
 * Dialog panel. Capped to the positioner's height and scrolls past it, so a tall
 * dialog never runs off screen with its actions unreachable
 */
const DialogContent = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Content>) => (
  <ArkDialog.Content
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-top-[2%] data-[state=open]:slide-in-from-top-[2%] relative grid max-h-full w-full max-w-lg gap-4 overflow-y-auto overscroll-contain border bg-background p-6 rounded-lg shadow-lg duration-200 data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const DialogTitle = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Title>) => (
  <ArkDialog.Title
    className={cn(
      "font-semibold text-lg leading-none tracking-tight",
      className,
    )}
    {...rest}
  />
);

const DialogDescription = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Description>) => (
  <ArkDialog.Description
    className={cn("text-muted-foreground text-sm", className)}
    {...rest}
  />
);

const DialogCloseTrigger = ({
  className,
  children,
  asChild,
  ...rest
}: ComponentProps<typeof ArkDialog.CloseTrigger>) => {
  // If there are no children, render the default X icon
  if (!children) {
    return (
      <ArkDialog.CloseTrigger
        className={cn(
          "absolute top-4 right-4 cursor-pointer rounded opacity-70 outline-none ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 disabled:pointer-events-none",
          className,
        )}
        {...rest}
      >
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </ArkDialog.CloseTrigger>
    );
  }

  // If children are provided, use them inside the CloseTrigger
  // This is useful for creating buttons that close the dialog
  return (
    <ArkDialog.CloseTrigger className={className} asChild={asChild} {...rest}>
      {children}
    </ArkDialog.CloseTrigger>
  );
};

export {
  DialogBackdrop,
  DialogCloseTrigger,
  DialogContent,
  DialogContext,
  DialogDescription,
  DialogPortal,
  DialogPositioner,
  DialogProvider,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
};

import { cn } from "@/lib/utils";

import type { ComponentProps } from "react";

/**
 * Text label for a form control. Pair with a control's `id` via `htmlFor`.
 */
const Label = ({ className, ...rest }: ComponentProps<"label">) => (
  // biome-ignore lint/a11y/noLabelWithoutControl: generic primitive; the control association (htmlFor) is supplied by the consumer via spread props
  <label
    className={cn(
      "font-medium text-sm leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70",
      className,
    )}
    {...rest}
  />
);

export { Label };

import { Eye, EyeOff } from "lucide-react";
import { useState } from "react";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/thornberry/components/button";
import { Input } from "@/registry/thornberry/components/input";

import type { ComponentProps } from "react";

/**
 * A password input with a show/hide toggle. Standalone (not tied to a form
 * context) so it can be used both inside form fields and on its own (e.g. a 2FA
 * password prompt). The toggle is disabled while the field is empty.
 */
const PasswordInput = ({
  className,
  ...props
}: ComponentProps<typeof Input>) => {
  const [showPassword, setShowPassword] = useState(false);

  const disabled =
    props.value === "" || props.value === undefined || props.disabled;

  return (
    <div className="relative">
      <Input
        {...props}
        type={showPassword ? "text" : "password"}
        className={cn("pr-9", className)}
      />

      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="text-muted-foreground hover:text-foreground absolute top-0 right-0 size-9"
        onClick={() => setShowPassword((prev) => !prev)}
        disabled={disabled}
        aria-label={showPassword ? "Hide password" : "Show password"}
      >
        {showPassword && !disabled ? (
          <Eye className="size-4" aria-hidden="true" />
        ) : (
          <EyeOff className="size-4" aria-hidden="true" />
        )}
      </Button>
    </div>
  );
};

export { PasswordInput };

import { Shuffle } from "lucide-react";
import { useEffect, useState } from "react";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/thornberry/components/button";

/**
 * One example prompt. `label` is the short chip text; `prompt` is what a pick
 * drafts into the composer, when it should be fuller than the label
 */
export interface PromptSuggestion {
  label: string;
  prompt?: string;
}

export interface PromptSuggestionsProps {
  /** Every example to draw from; a string is both the label and the prompt */
  suggestions: readonly (string | PromptSuggestion)[];
  /** How many chips show at once. Defaults to 4 */
  count?: number;
  /**
   * Called with the picked example's prompt. Draft it into the composer and
   * focus it, so the user can edit it before sending; never send it outright
   */
  onPick: (prompt: string, suggestion: PromptSuggestion) => void;
  /**
   * Show a control that swaps in the next set of examples. Defaults to on
   * whenever there are more examples than `count`
   */
  shuffle?: boolean;
  /** Text of the shuffle control. Defaults to "More ideas" */
  shuffleLabel?: string;
  /** Accessible name of the chip group. Defaults to "Example prompts" */
  label?: string;
  disabled?: boolean;
  className?: string;
  /**
   * Random source for the order the examples are drawn in, in [0, 1). Defaults
   * to `Math.random`; pass a fixed one for a stable order in tests or stories
   */
  random?: () => number;
}

const normalize = (suggestion: string | PromptSuggestion): PromptSuggestion =>
  typeof suggestion === "string" ? { label: suggestion } : suggestion;

/**
 * A shuffled order of `length` indexes (Fisher-Yates), so every visit starts
 * from a different set and "More ideas" walks through them all before repeating
 */
export const shuffledOrder = (
  length: number,
  random: () => number = Math.random,
): number[] => {
  const order = Array.from({ length }, (_, index) => index);

  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    const swap = order[i] as number;

    order[i] = order[j] as number;
    order[j] = swap;
  }

  return order;
};

/** The `count` indexes shown at window `page` of `order`, wrapping around */
export const suggestionWindow = (
  order: readonly number[],
  page: number,
  count: number,
): number[] => {
  if (!order.length) return [];

  const size = Math.min(count, order.length);
  const start = (page * size) % order.length;

  return Array.from(
    { length: size },
    (_, offset) => order[(start + offset) % order.length] as number,
  );
};

/**
 * Example prompt chips for an empty composer: a few short, concrete examples
 * drawn in a random order per visit, and a "More ideas" control that swaps in
 * the next few. Picking one hands its prompt to the host to draft into the
 * composer (never to send), so the user can edit it first. The host decides
 * when to show it, typically while the conversation is empty and the composer
 * is blank.
 *
 * The order is shuffled after mount, so a server render and its hydration
 * agree; until then the first examples hold the space, hidden
 */
const PromptSuggestions = ({
  suggestions,
  count = 4,
  onPick,
  shuffle,
  shuffleLabel = "More ideas",
  label = "Example prompts",
  disabled = false,
  className,
  random,
}: PromptSuggestionsProps) => {
  const items = suggestions.map(normalize);
  const [order, setOrder] = useState<number[] | null>(null);
  const [page, setPage] = useState(0);

  // Shuffle on the client only, once per mount (a visit) and whenever the
  // examples themselves change
  // biome-ignore lint/correctness/useExhaustiveDependencies: reshuffle when the list's size changes, not on every render's new array
  useEffect(() => {
    setOrder(shuffledOrder(items.length, random));
    setPage(0);
  }, [items.length]);

  if (!items.length) return null;

  const ready = order !== null && order.length === items.length;
  const shown = suggestionWindow(
    ready ? order : items.map((_, index) => index),
    page,
    count,
  );
  const canShuffle = shuffle ?? items.length > count;

  return (
    <div
      role="group"
      aria-label={label}
      className={cn(
        "flex flex-wrap items-center gap-2 transition-opacity duration-200",
        ready ? "opacity-100" : "invisible opacity-0",
        className,
      )}
    >
      {shown.map((index) => {
        const item = items[index] as PromptSuggestion;

        return (
          <Button
            key={`${index}-${item.label}`}
            type="button"
            variant="outline"
            size="sm"
            disabled={disabled}
            onClick={() => onPick(item.prompt ?? item.label, item)}
            className="h-auto min-h-8 max-w-full rounded-full py-1.5 text-left whitespace-normal pointer-coarse:min-h-11"
          >
            {item.label}
          </Button>
        );
      })}

      {canShuffle && (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={disabled}
          onClick={() => setPage((current) => current + 1)}
          className="text-muted-foreground rounded-full pointer-coarse:min-h-11"
        >
          <Shuffle aria-hidden="true" />
          {shuffleLabel}
        </Button>
      )}
    </div>
  );
};

export { PromptSuggestions };

import { ark } from "@ark-ui/react";

import { cn } from "@/lib/utils";

import type { ComponentProps } from "react";

// TODO: add label
const Input = ({ className, ...rest }: ComponentProps<typeof ark.input>) => (
  <ark.input
    className={cn(
      "flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 shadow-sm transition-colors file:border-0 file:bg-transparent file:font-medium file:text-foreground file:text-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
      className,
    )}
    {...rest}
  />
);

export { Input };
